import { readFileSync, writeFileSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const root = join(__dirname, '..');
const j = JSON.parse(
  readFileSync(join(root, 'supabase/seed/pharma_sm_metrics_default.json'), 'utf8'),
);

let sql =
  '-- Auto-generated by scripts/gen-pharma-sm-metrics-sql.mjs from pharma_sm_metrics_default.json\n';

const vals = j.rows.map((r) => {
  const esc = (s) => String(s).replace(/'/g, "''");
  const cardJson = esc(JSON.stringify(r.card));
  return `  (NULL, NULL, '${esc(r.metric_key)}', '${cardJson}'::jsonb, ${r.sort_order})`;
});

sql +=
  'INSERT INTO public.pharma_sm_metrics (company_id, brand_id, metric_key, card, sort_order)\n';
sql += 'VALUES\n';
sql += vals.join(',\n');
sql += '\nON CONFLICT DO NOTHING;\n';

writeFileSync(
  join(root, 'supabase/migrations/20260318100001_seed_pharma_sm_metrics_global.sql'),
  sql,
);
console.log('Wrote seed migration with', j.rows.length, 'rows');
